<?php
declare(strict_types=1);
require __DIR__.'/bootstrap.php';if(empty($_SESSION['admin_id']))redirect('index.php');
require_once dirname(__DIR__).'/private/cash_assets.php';require_once dirname(__DIR__).'/private/ui.php';
$view=($_GET['view']??'cash')==='assets'?'assets':'cash';$id=max(0,(int)($_GET['id']??0));$base='cash_assets.php?view='.$view;
if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{
 $action=(string)($_POST['action']??'');$admin=(int)$_SESSION['admin_id'];$request=(string)($_POST['request_key']??'');$version=isset($_POST['row_version'])?filter_var($_POST['row_version'],FILTER_VALIDATE_INT):null;if($version===false||($version!==null&&$version<0))throw new InvalidArgumentException('Versionsstand ungültig.');
 if($action==='initialize')cashInitialize($pdo,$admin,(string)($_POST['date']??''),financeCents((string)($_POST['amount']??''),'de'),(string)($_POST['note']??''));
 elseif($action==='transfer')cashTransfer($pdo,$admin,(string)($_POST['kind']??''),(string)($_POST['date']??''),financeCents((string)($_POST['amount']??''),'de'),(string)($_POST['description']??''),$request);
 elseif($action==='payment')cashLinkPayment($pdo,$admin,(int)($_POST['payment_id']??0),$request,!empty($_POST['physical_confirmed']));
 elseif($action==='reverse')cashReverseTransfer($pdo,$admin,(int)($_POST['entry_id']??0),(string)($_POST['date']??''),(string)($_POST['reason']??''),$request);
 elseif($action==='asset_save')$id=assetSave($pdo,$admin,$_POST,$request,$id,$version);
 elseif($action==='asset_plan')assetSetPlan($pdo,$admin,$id,(int)($_POST['year']??0),financeCents((string)($_POST['amount']??''),'de'),$version);
 elseif($action==='asset_approve')assetApprove($pdo,$admin,$id,$version,(string)($_POST['review_reference']??''),!empty($_POST['reviewed']));
 elseif($action==='asset_retire')assetRetire($pdo,$admin,$id,$version,(string)($_POST['date']??''),(string)($_POST['reason']??''));
 else throw new InvalidArgumentException('Aktion unbekannt.');$_SESSION['app_notice']='Gespeichert. Keine Bankaktion und keine zusätzliche EÜR-Buchung durch dieses Modul.';
 }catch(Throwable $e){gszUiError($e);}redirect($base.($id?'&id='.$id:''));}
$data=null;$unlinked=[];$reversals=[];$assets=[];$asset=null;$plan=[];$history=[];$documents=[];$properties=[];$schedule=null;
try{cashAssetsRequire($pdo);if($view==='cash'){$data=cashData($pdo);$unlinked=cashUnlinkedPayments($pdo);$reversals=cashUnlinkedReversals($pdo);if(($_GET['format']??'')==='csv'){$csv=cashCsv($data);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="gsz-kasse.csv"');echo $csv;exit;}}
 else{if(($_GET['format']??'')==='csv'){$csv=assetRegisterCsv($pdo);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="gsz-anlagen-manueller-plan.csv"');echo $csv;exit;}$assets=$pdo->query('SELECT id,number,name,status,acquisition_cents,retired_on FROM asset_register ORDER BY id DESC LIMIT 200')->fetchAll();$documents=$pdo->query('SELECT id,title,original_name FROM documents ORDER BY id DESC LIMIT 1000')->fetchAll();$properties=$pdo->query('SELECT id,name FROM properties ORDER BY name,id LIMIT 1000')->fetchAll();if($id){$q=$pdo->prepare('SELECT * FROM asset_register WHERE id=?');$q->execute([$id]);$asset=$q->fetch();if(!$asset)throw new RuntimeException('Anlage nicht gefunden.');$q=$pdo->prepare('SELECT year,amount_cents FROM asset_plan_rows WHERE asset_id=? ORDER BY year');$q->execute([$id]);$plan=$q->fetchAll();$schedule=assetSchedule($asset,$plan);$q=$pdo->prepare('SELECT action,detail_json,created_at FROM asset_events WHERE asset_id=? ORDER BY id DESC LIMIT 30');$q->execute([$id]);$history=$q->fetchAll();if(!array_filter($documents,fn($d)=>(int)$d['id']===(int)$asset['document_id'])){$q=$pdo->prepare('SELECT id,title,original_name FROM documents WHERE id=?');$q->execute([$asset['document_id']]);if($d=$q->fetch())array_unshift($documents,$d);}if($asset['property_id']&&!array_filter($properties,fn($p)=>(int)$p['id']===(int)$asset['property_id'])){$q=$pdo->prepare('SELECT id,name FROM properties WHERE id=?');$q->execute([$asset['property_id']]);if($p=$q->fetch())array_unshift($properties,$p);}}}
}catch(Throwable $e){gszUiError($e);}gszPageStart($view==='cash'?'Kassenbuch':'Anlagenverzeichnis');
function caFields(string $action,?array $record=null):void{gszFields($action);echo '<input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';if($record!==null)echo '<input type="hidden" name="row_version" value="'.(int)$record['row_version'].'">';}
function caEuro(int $cents):string{return str_replace('.',',',financeDecimal($cents));}
